mapper.sql:
FROM ph_inv_damage d
WHERE d.tenant_id = #{scope.tenantId} AND d.store_id = #{scope.storeId} AND d.deleted = b'0'
AND d.status = #{q.status}
AND d.damage_type = #{q.damageType}

    AND EXISTS (SELECT 1 FROM ph_inv_damage_line dl
                JOIN ph_inv_batch b ON b.id = dl.batch_id AND b.tenant_id = dl.tenant_id
                WHERE dl.damage_id = d.id AND dl.tenant_id = d.tenant_id AND dl.deleted = b'0'
                  AND b.store_id = #{scope.storeId} AND b.warehouse_id = #{q.warehouseId}
                  AND b.deleted = b'0')

mapper.select:
SELECT d.id, d.damage_no, d.store_id, d.damage_type, d.reason, d.total_qty, d.total_amount,
       d.status, d.audit_by, d.audit_at, d.execute_by, d.execute_at, d.review_by, d.create_time

ORDER BY d.id DESC LIMIT #{q.pageSize} OFFSET #{q.offset}

mapper.update:
UPDATE ph_inv_damage
SET status = #{to}, updater = #{operator}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id} AND tenant_id = #{scope.tenantId} AND store_id = #{scope.storeId}
  AND deleted = b'0' AND status = #{from}
